from .attenuator_factory import AttenuatorFactory


class AttenuatorFacade(object):
    @staticmethod
    def setup_attenuator(attenuator=None, **kwargs):
        device = AttenuatorFactory.create(attenuator=attenuator, **kwargs)
        return device

    @staticmethod
    def set_port_attenuation(
        port, attenuation_value, attenuator, confirm=False, confirmation_delay=1
    ):
        return attenuator.set_port_attenuation(
            port=port,
            attenuation_value=attenuation_value,
            confirm=confirm,
            confirmation_delay=confirmation_delay,
        )

    @staticmethod
    def read_port_attenuation(port, attenuator):
        return attenuator.read_port_attenuation(port=port)

    @staticmethod
    def set_ports_attenuation(
        ports, attenuation_values, attenuator, confirm=False, confirmation_delay=1
    ):
        return attenuator.set_ports_attenuation(
            ports=ports,
            attenuation_values=attenuation_values,
            confirm=confirm,
            confirmation_delay=confirmation_delay,
        )

    @staticmethod
    def read_ports_attenuation(ports, attenuator):
        return attenuator.read_ports_attenuation(ports=ports)

    @staticmethod
    def set_linear_fading_scenario(
        port, start_value, end_value, interval, unit, attenuator
    ):
        return attenuator.set_linear_fading_scenario(
            port=port,
            start_value=start_value,
            end_value=end_value,
            interval=interval,
            unit=unit,
        )

    @staticmethod
    def set_ports_fading_attenuation(set_fading_scenarios, attenuator, timeout):
        return attenuator.set_ports_fading_attenuation(
            set_fading_scenarios=set_fading_scenarios, timeout=timeout
        )

    @staticmethod
    def escape_command(attenuator):
        return attenuator.escape_command()

    @staticmethod
    def disconnect(attenuator):
        return attenuator.disconnect()
